*** Begin Patch
*** Add File: output/assets/styles.css
+:root{
+  --bg:#f5f5f7;
+  --surface:#ffffff;
+  --text:#1d1d1f;
+  --muted:#6e6e73;
+  --link:#06c;
+  --hairline:rgba(29,29,31,.12);
+  --shadow:0 8px 28px rgba(0,0,0,.08);
+  --radius:20px;
+  --radius-sm:14px;
+  --container:1120px;
+  --nav-h:52px;
+  --section-nav-h:52px;
+}
+
+*{box-sizing:border-box}
+html{scroll-behavior:smooth}
+body{
+  margin:0;
+  background:var(--bg);
+  color:var(--text);
+  font-family:ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"SF Pro Display","SF Pro Text","Helvetica Neue",Arial,sans-serif;
+  line-height:1.35;
+  -webkit-font-smoothing:antialiased;
+  -moz-osx-font-smoothing:grayscale;
+}
+
+a{color:var(--link);text-decoration:none}
+a:hover{text-decoration:underline}
+
+.skip-link{
+  position:absolute;
+  left:-999px;
+  top:8px;
+  background:#000;
+  color:#fff;
+  padding:10px 12px;
+  border-radius:10px;
+  z-index:1000;
+}
+.skip-link:focus{left:8px}
+
+.topnav{
+  position:sticky;
+  top:0;
+  z-index:40;
+  background:rgba(245,245,247,.82);
+  backdrop-filter:saturate(180%) blur(14px);
+  border-bottom:1px solid var(--hairline);
+}
+
+.topnav__inner{
+  height:var(--nav-h);
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:14px;
+  max-width:var(--container);
+  padding:0 18px;
+  margin:0 auto;
+}
+
+.brand{
+  display:flex;
+  align-items:center;
+  gap:10px;
+  font-weight:650;
+  letter-spacing:.2px;
+  color:inherit;
+}
+
+.brand__mark{
+  width:26px;
+  height:26px;
+  border-radius:8px;
+  background:linear-gradient(135deg,#111 0%, #2d2d30 60%, #585861 100%);
+  box-shadow:0 6px 18px rgba(0,0,0,.15);
+}
+
+.navlinks{
+  display:flex;
+  align-items:center;
+  gap:18px;
+  flex-wrap:wrap;
+}
+.navlinks a{
+  color:inherit;
+  font-size:13px;
+  padding:8px 10px;
+  border-radius:999px;
+}
+.navlinks a[aria-current="page"]{
+  background:rgba(29,29,31,.08);
+}
+
+.container{
+  max-width:var(--container);
+  margin:0 auto;
+  padding:0 18px;
+}
+
+.ribbon{
+  background:#fff;
+  border-bottom:1px solid var(--hairline);
+}
+.ribbon__inner{
+  max-width:var(--container);
+  margin:0 auto;
+  padding:10px 18px;
+  display:flex;
+  gap:10px;
+  align-items:center;
+  justify-content:center;
+  font-size:13px;
+  color:var(--muted);
+}
+
+.ribbon__inner a{white-space:nowrap}
+
+.hero{
+  padding:40px 0 24px;
+}
+.hero h1{
+  margin:0;
+  font-size:52px;
+  letter-spacing:-.02em;
+  line-height:1.05;
+}
+.hero p{
+  margin:12px 0 0;
+  font-size:18px;
+  color:var(--muted);
+}
+.hero__ctas{
+  margin-top:18px;
+  display:flex;
+  flex-wrap:wrap;
+  gap:10px;
+}
+
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap:8px;
+  padding:10px 14px;
+  border-radius:999px;
+  border:1px solid var(--hairline);
+  background:rgba(255,255,255,.7);
+  color:inherit;
+  font-size:13px;
+  line-height:1;
+}
+.btn:hover{background:#fff;text-decoration:none}
+.btn--primary{
+  background:var(--text);
+  color:#fff;
+  border-color:rgba(29,29,31,.25);
+}
+.btn--primary:hover{background:#000}
+.btn--ghost{
+  background:transparent;
+}
+
+.section{
+  padding:32px 0;
+}
+
+.section__head{
+  display:flex;
+  align-items:flex-end;
+  justify-content:space-between;
+  gap:18px;
+  margin-bottom:14px;
+}
+
+.kicker{
+  font-size:13px;
+  color:var(--muted);
+  letter-spacing:.02em;
+  text-transform:none;
+}
+
+.section__title{
+  margin:0;
+  font-size:32px;
+  letter-spacing:-.015em;
+}
+
+.section__sub{
+  margin:6px 0 0;
+  color:var(--muted);
+  max-width:70ch;
+}
+
+.grid{
+  display:grid;
+  grid-template-columns:repeat(12,1fr);
+  gap:16px;
+}
+
+.tile{
+  border-radius:var(--radius);
+  overflow:hidden;
+  background:var(--surface);
+  box-shadow:var(--shadow);
+  border:1px solid rgba(29,29,31,.08);
+  min-height:360px;
+  display:flex;
+  position:relative;
+}
+
+.tile__content{
+  padding:26px;
+  display:flex;
+  flex-direction:column;
+  gap:10px;
+  width:52%;
+  min-width:280px;
+}
+
+.tile__title{
+  margin:0;
+  font-size:30px;
+  letter-spacing:-.02em;
+  line-height:1.1;
+}
+
+.tile__tag{
+  margin:0;
+  color:var(--muted);
+}
+
+.tile__ctas{display:flex;gap:10px;flex-wrap:wrap;margin-top:6px}
+
+.tile__media{
+  flex:1;
+  display:flex;
+  align-items:center;
+  justify-content:center;
+  padding:24px;
+}
+
+.product-art{
+  width:min(420px,100%);
+  aspect-ratio:4/3;
+  border-radius:24px;
+  background:linear-gradient(135deg,#e9ecff 0%, #f7f8ff 40%, #ffffff 100%);
+  border:1px solid rgba(29,29,31,.08);
+  position:relative;
+  overflow:hidden;
+}
+
+.product-art::before{
+  content:"";
+  position:absolute;
+  inset:-40% -30% auto auto;
+  width:260px;
+  height:260px;
+  border-radius:50%;
+  background:radial-gradient(circle at 30% 30%, rgba(0,102,204,.22), rgba(0,102,204,0));
+}
+
+.product-art::after{
+  content:"";
+  position:absolute;
+  inset:auto auto -55% -45%;
+  width:340px;
+  height:340px;
+  border-radius:50%;
+  background:radial-gradient(circle at 60% 60%, rgba(29,29,31,.14), rgba(29,29,31,0));
+}
+
+.art-label{
+  position:absolute;
+  left:18px;
+  top:16px;
+  font-size:12px;
+  color:rgba(29,29,31,.6);
+}
+
+.art-device{
+  position:absolute;
+  left:20px;
+  right:20px;
+  bottom:18px;
+  height:58%;
+  border-radius:20px;
+  background:linear-gradient(180deg, rgba(0,0,0,.08), rgba(0,0,0,.02));
+  border:1px solid rgba(29,29,31,.10);
+}
+
+.tile--dark{color:#fff;background:linear-gradient(135deg,#0d0d10 0%, #1b1b20 55%, #2e2e33 100%)}
+.tile--dark .tile__tag{color:rgba(255,255,255,.72)}
+.tile--dark .btn{border-color:rgba(255,255,255,.22);color:#fff;background:rgba(255,255,255,.08)}
+.tile--dark .btn:hover{background:rgba(255,255,255,.12)}
+.tile--dark .btn--primary{background:#fff;color:#000}
+.tile--dark .btn--primary:hover{background:#f2f2f2}
+.tile--warm{background:linear-gradient(135deg,#fff 0%, #fff2f0 50%, #fff 100%)}
+.tile--cool{background:linear-gradient(135deg,#fff 0%, #eef5ff 55%, #fff 100%)}
+
+.tile--span-6{grid-column:span 6}
+.tile--span-12{grid-column:span 12}
+
+.carousel{
+  position:relative;
+}
+
+.carousel__viewport{
+  display:grid;
+  grid-auto-flow:column;
+  grid-auto-columns:minmax(260px, 320px);
+  gap:14px;
+  overflow-x:auto;
+  overscroll-behavior-x:contain;
+  scroll-snap-type:x mandatory;
+  scroll-padding:18px;
+  padding:6px 2px 14px;
+  margin:0 -2px;
+  scrollbar-width:none;
+}
+.carousel__viewport::-webkit-scrollbar{display:none}
+
+.card{
+  scroll-snap-align:start;
+  background:var(--surface);
+  border:1px solid rgba(29,29,31,.08);
+  border-radius:var(--radius);
+  box-shadow:0 10px 30px rgba(0,0,0,.06);
+  padding:18px;
+  min-height:210px;
+  display:flex;
+  flex-direction:column;
+  gap:10px;
+}
+
+.card__top{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}
+.badge{
+  font-size:11px;
+  letter-spacing:.08em;
+  text-transform:uppercase;
+  padding:6px 8px;
+  border-radius:999px;
+  background:rgba(0,102,204,.10);
+  color:#064b98;
+}
+
+.card__title{margin:0;font-size:18px;letter-spacing:-.01em}
+.card__desc{margin:0;color:var(--muted);font-size:13px}
+.price{
+  font-weight:650;
+  font-size:14px;
+}
+.monthly{color:var(--muted);font-size:12px}
+
+.card__art{
+  margin-top:auto;
+  border-radius:16px;
+  border:1px solid rgba(29,29,31,.08);
+  background:linear-gradient(135deg,#f0f1f6 0%, #fff 60%);
+  height:110px;
+  position:relative;
+  overflow:hidden;
+}
+.card__art::after{
+  content:"";
+  position:absolute;
+  inset:auto -30% -70% auto;
+  width:240px;
+  height:240px;
+  border-radius:50%;
+  background:radial-gradient(circle at 30% 30%, rgba(0,102,204,.18), rgba(0,102,204,0));
+}
+
+.carousel__nav{
+  display:flex;
+  gap:10px;
+}
+
+.icon-btn{
+  width:40px;
+  height:40px;
+  border-radius:999px;
+  border:1px solid var(--hairline);
+  background:rgba(255,255,255,.75);
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  cursor:pointer;
+}
+.icon-btn:hover{background:#fff}
+.icon-btn:disabled{opacity:.35;cursor:not-allowed}
+
+.icon-btn svg{width:18px;height:18px}
+
+.tabs{
+  display:flex;
+  gap:8px;
+  flex-wrap:wrap;
+}
+
+.tab{
+  appearance:none;
+  border:1px solid var(--hairline);
+  border-radius:999px;
+  background:rgba(255,255,255,.7);
+  padding:10px 12px;
+  font-size:13px;
+  cursor:pointer;
+  color:inherit;
+}
+.tab[aria-selected="true"]{background:#fff;border-color:rgba(29,29,31,.20)}
+
+.tabpanels{margin-top:14px}
+.tabpanel[hidden]{display:none}
+
+.pillbar{
+  display:grid;
+  grid-auto-flow:column;
+  grid-auto-columns:max-content;
+  gap:10px;
+  overflow:auto;
+  padding:10px 0;
+  scrollbar-width:none;
+}
+.pillbar::-webkit-scrollbar{display:none}
+
+.pill{
+  border:1px solid var(--hairline);
+  border-radius:999px;
+  padding:10px 12px;
+  background:rgba(255,255,255,.68);
+  font-size:13px;
+  color:inherit;
+  display:inline-flex;
+  align-items:center;
+  gap:10px;
+  cursor:pointer;
+}
+
+.pill:hover{text-decoration:none;background:#fff}
+.pill__dot{
+  width:18px;
+  height:18px;
+  border-radius:7px;
+  background:linear-gradient(135deg,#d9d9df,#fefefe);
+  border:1px solid rgba(29,29,31,.10);
+}
+
+.section-nav{
+  position:sticky;
+  top:var(--nav-h);
+  z-index:35;
+  background:rgba(245,245,247,.88);
+  backdrop-filter:saturate(180%) blur(14px);
+  border-bottom:1px solid var(--hairline);
+}
+
+.section-nav__inner{
+  max-width:var(--container);
+  margin:0 auto;
+  padding:0 18px;
+  height:var(--section-nav-h);
+  display:flex;
+  align-items:center;
+  gap:10px;
+  overflow:auto;
+  scrollbar-width:none;
+}
+.section-nav__inner::-webkit-scrollbar{display:none}
+
+.section-link{
+  display:inline-flex;
+  align-items:center;
+  padding:10px 12px;
+  border-radius:999px;
+  border:1px solid transparent;
+  color:inherit;
+  font-size:13px;
+  white-space:nowrap;
+}
+.section-link[aria-current="true"]{
+  border-color:rgba(29,29,31,.18);
+  background:#fff;
+}
+
+.footer{
+  margin-top:40px;
+  padding:26px 0 36px;
+  background:rgba(255,255,255,.65);
+  border-top:1px solid var(--hairline);
+}
+
+.footer__grid{
+  display:grid;
+  grid-template-columns:repeat(4,1fr);
+  gap:16px;
+}
+
+.footer__col{
+  background:transparent;
+}
+
+.footer__title{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  width:100%;
+  background:transparent;
+  border:0;
+  padding:10px 0;
+  font-size:12px;
+  letter-spacing:.02em;
+  color:rgba(29,29,31,.88);
+  text-transform:none;
+  font-weight:650;
+  cursor:default;
+}
+
+.footer__title svg{display:none}
+
+.footer__links{display:grid;gap:8px;padding:0 0 14px}
+.footer__links a{font-size:12px;color:var(--muted)}
+.footer__links a:hover{color:var(--text)}
+
+.legal{
+  margin-top:10px;
+  padding-top:14px;
+  border-top:1px solid var(--hairline);
+  color:var(--muted);
+  font-size:11px;
+  line-height:1.4;
+}
+
+.quick-links{
+  display:flex;
+  gap:10px;
+  flex-wrap:wrap;
+}
+
+.quick-links a{
+  border:1px solid var(--hairline);
+  background:rgba(255,255,255,.72);
+  padding:10px 12px;
+  border-radius:999px;
+  font-size:13px;
+  color:inherit;
+}
+.quick-links a:hover{background:#fff;text-decoration:none}
+
+.two-col{
+  display:grid;
+  grid-template-columns:1.1fr .9fr;
+  gap:16px;
+}
+
+.panel{
+  background:rgba(255,255,255,.7);
+  border:1px solid rgba(29,29,31,.08);
+  border-radius:var(--radius);
+  box-shadow:0 10px 28px rgba(0,0,0,.05);
+  padding:18px;
+}
+
+.list{
+  display:grid;
+  gap:10px;
+}
+
+.list-item{
+  display:flex;
+  gap:12px;
+  align-items:flex-start;
+}
+
+.list-item__icon{
+  width:36px;
+  height:36px;
+  border-radius:14px;
+  border:1px solid rgba(29,29,31,.10);
+  background:linear-gradient(135deg,#ffffff 0%, #efeff4 100%);
+}
+
+.list-item__title{margin:0;font-weight:650;font-size:14px}
+.list-item__desc{margin:2px 0 0;color:var(--muted);font-size:13px}
+
+@media (max-width: 980px){
+  .tile{flex-direction:column;min-height:440px}
+  .tile__content{width:100%}
+  .tile__media{padding:14px 22px 24px}
+  .grid{gap:12px}
+  .tile--span-6{grid-column:span 12}
+  .hero h1{font-size:44px}
+  .two-col{grid-template-columns:1fr}
+  .footer__grid{grid-template-columns:repeat(2,1fr)}
+}
+
+@media (max-width: 700px){
+  .hero{padding:30px 0 16px}
+  .hero h1{font-size:40px}
+  .section__title{font-size:26px}
+  .topnav__inner{gap:10px}
+  .navlinks{gap:8px}
+  .navlinks a{padding:8px 8px}
+  .footer__grid{grid-template-columns:1fr}
+  .footer__title{cursor:pointer}
+  .footer__title svg{display:block;width:16px;height:16px;opacity:.55}
+  .footer__links{display:none;padding-top:6px}
+  .footer__col[data-open="true"] .footer__links{display:grid}
+}
+
+@media (prefers-reduced-motion: reduce){
+  html{scroll-behavior:auto}
+  .carousel__viewport{scroll-behavior:auto}
+}
+
*** End Patch

